// Writes src/surface.ts: the tools and commands keel registers, as the core
// defines them (lisp/src/surface.lisp, op surface). A host registers them at
// load, before a core may be built, so the binding reads them from this file;
// tests/surface.test.ts fails when it says other than the core. After a change
// to surface.lisp or names.lisp:
//   bun --preload ./tests/support/core-on.ts scripts/surface.ts
import { writeFileSync } from "fs";
import { join } from "path";
import { core } from "../src/core";

export const surfaceSource = (surface: unknown): string => [
  "// Generated by scripts/surface.ts from the core (lisp/src/surface.lisp): edit that, not this.",
  `export const SURFACE = ${JSON.stringify(surface, null, 2)} as const;`,
  "",
].join("\n");

if (import.meta.main) writeFileSync(join(import.meta.dir, "../src/surface.ts"), surfaceSource(core({ op: "surface" }).surface));
